package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	s := sc.Text()

	// ここから下を書く: strconv.Atoi で変換し、
	// err != nil なら「数値ではありません」、成功なら 2 倍を出力する
	_ = s
	_ = strconv.Atoi
	_ = fmt.Println
}

